@@ -247,3 +248,31 @@ describe('ZimmCountryLanguageMismatch', () => {
     });
   });
 });
+
+// SFCC-831/689 rework (Finding 4a, UNIFORM U1) — `VARIATION_CONFIG` (this component's own copy
+// fallbacks) and `ENTRIES` (seedRegionalPromptUiCopy.mjs's Contentful English values) used to be
+// two independently hand-typed copies of the same 8 strings, with nothing but a docblock comment
+// in each file asserting they matched. This imports both real sources and proves they still agree,
+// keyed by each seed entry's own `key` (not array position) so either list can be reordered without
+// breaking the comparison, and so a genuine mismatch names which key failed.
+describe('seedRegionalPromptUiCopy.mjs stays in sync with VARIATION_CONFIG fallbacks (Finding 4a)', () => {
+  const SEED_KEY_TO_VARIATION_FALLBACK: ReadonlyArray<readonly [string, string]> = [
+    ['regional.locationPrompt.heading', VARIATION_CONFIG.location.headingFallback],
+    ['regional.locationPrompt.body', VARIATION_CONFIG.location.bodyFallback],
+    ['regional.locationPrompt.cta.switch', VARIATION_CONFIG.location.switchCtaFallback],
+    ['regional.locationPrompt.cta.stay', VARIATION_CONFIG.location.stayCtaFallback],
+    ['regional.languagePrompt.heading', VARIATION_CONFIG.language.headingFallback],
+    ['regional.languagePrompt.body', VARIATION_CONFIG.language.bodyFallback],
+    ['regional.languagePrompt.cta.switch', VARIATION_CONFIG.language.switchCtaFallback],
+    ['regional.languagePrompt.cta.stay', VARIATION_CONFIG.language.stayCtaFallback],
+  ];
+
+  test.each(SEED_KEY_TO_VARIATION_FALLBACK)(
+    'seed entry "%s" value matches its VARIATION_CONFIG fallback',
+    (key, expectedValue) => {
+      const entry = ENTRIES.find((seedEntry) => seedEntry.key === key);
+      expect(entry).toBeDefined();
+      expect(entry?.value).toBe(expectedValue);
+    },
+  );
+});

