1	/**
2	 * Shared utilities for Contentful setup scripts.
3	 * Provides client factory, env validation, and environment polling.
4	 */
5	
6	import { createClient as createCMAClient } from 'contentful-management';
7	
8	export const log = {
9	  info: (msg) => console.log(`  ℹ️  ${msg}`),
10	  success: (msg) => console.log(`  ✅  ${msg}`),
11	  skip: (msg) => console.log(`  ⏭️   ${msg}`),
12	  warn: (msg) => console.warn(`  ⚠️  ${msg}`),
13	  error: (msg) => console.error(`  ❌  ${msg}`),
14	  section: (msg) => console.log(`\n── ${msg} ──`),
15	};
16	
17	/**
18	 * Validates that the required environment variables are set and non-empty.
19	 * Exits the process with a descriptive message if any are missing.
20	 * @param {string[]} required
21	 */
22	export function checkEnv(required) {
23	  const missing = required.filter((k) => !process.env[k]);
24	  if (missing.length) {
25	    log.error(`Missing env vars: ${missing.join(', ')}`);
26	    console.error('   Add them to .env (at repo root) and re-run.\n');
27	    process.exit(1);
28	  }
29	}
30	
31	/**
32	 * Creates a contentful-management plain client scoped to the project space.
33	 * @returns {import('contentful-management').PlainClientAPI}
34	 */
35	export function createClient() {
36	  return createCMAClient(
37	    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
38	    {
39	      type: 'plain',
40	      defaults: { spaceId: process.env.CONTENTFUL_SPACE_ID },
41	    },
42	  );
43	}
44	
45	/**
46	 * Polls an environment until its status is 'ready', then returns it.
47	 * Contentful creates environments asynchronously — this is required after create().
48	 * @param {import('contentful-management').PlainClientAPI} client
49	 * @param {string} environmentId
50	 * @param {number} [timeoutMs=120_000]
51	 * @returns {Promise<object>}
52	 */
53	export async function pollForReady(client, environmentId, timeoutMs = 120_000) {
54	  const deadline = Date.now() + timeoutMs;
55	  while (Date.now() < deadline) {
56	    try {
57	      const env = await client.environment.get({ environmentId });
58	      if (env.sys.status?.sys?.id === 'ready') return env;
59	    } catch (err) {
60	      // 404 immediately after create() is expected — environment is still being provisioned
61	      if (err.status !== 404) throw err;
62	    }
63	    await new Promise((r) => setTimeout(r, 3_000));
64	    process.stdout.write('.');
65	  }
66	  throw new Error(`Environment '${environmentId}' did not become ready within ${timeoutMs / 1000}s`);
67	}
68	
69	/**
70	 * Returns a sorted list of existing environment IDs in the space.
71	 * @param {import('contentful-management').PlainClientAPI} client
72	 * @returns {Promise<string[]>}
73	 */
74	export async function getExistingEnvironmentIds(client) {
75	  const { items } = await client.environment.getMany({ query: { limit: 100 } });
76	  return items.map((e) => e.sys.id);
77	}
78	
79	/**
80	 * Returns existing locale codes in a given environment.
81	 * @param {import('contentful-management').PlainClientAPI} client
82	 * @param {string} environmentId
83	 * @returns {Promise<string[]>}
84	 */
85	export async function getExistingLocaleCodes(client, environmentId) {
86	  const { items } = await client.locale.getMany({ environmentId, query: { limit: 100 } });
87	  return items.map((l) => l.code);
88	}
89	
90	/**
91	 * Parses a `--target <env>` flag from argv, defaulting to 'dev'. Exits the process with a
92	 * descriptive message if the flag is present but has no value following it — extracted verbatim
93	 * from the three seedXUiCopy.mjs scripts (SFCC-742's seedLoginDrawerUiCopy.mjs first, then
94	 * SFCC-831/689's seedRegionalPromptUiCopy.mjs and seedDrawerCloseUiCopy.mjs copied it), which had
95	 * each independently reimplemented this exact logic.
96	 * @param {string[]} [args]
97	 * @returns {string}
98	 */
99	export function resolveTarget(args = process.argv.slice(2)) {
100	  const i = args.indexOf('--target');
101	  const rawTarget = i !== -1 ? args[i + 1] : null;
102	  if (rawTarget === undefined) {
103	    // --target flag was present but no value followed it
104	    console.error('Error: --target requires a value, e.g. --target dev');
105	    process.exit(1);
106	  }
107	  return rawTarget ?? 'dev';
108	}
109	
110	/**
111	 * Seeds a list of `uiCopy` entries into a target Contentful environment: creates and publishes
112	 * any that don't yet exist, publishes any that exist only as an unpublished draft, and skips any
113	 * that are already published. Safe to re-run. Extracted verbatim from the same three scripts
114	 * {@link resolveTarget} was — see that function's own doc comment.
115	 * @param {import('contentful-management').PlainClientAPI} client
116	 * @param {string} target
117	 * @param {{ key: string; title: string; value: string; description: string }[]} entries
118	 * @returns {Promise<void>}
119	 */
120	export async function seedUiCopyEntries(client, target, entries) {
121	  log.section(`Seeding ${entries.length} uiCopy entries → environment: ${target}`);
122	
123	  // Fetch all existing uiCopy entries across pages before duplicate checks.
124	  // contentful-management paginates at 1,000 — a single request may miss entries.
125	  const existing = [];
126	  let skip = 0;
127	  let total = Infinity;
128	  while (existing.length < total) {
129	    const page = await client.entry.getMany({
130	      environmentId: target,
131	      query: { content_type: 'uiCopy', limit: 1000, skip },
132	    });
133	    total = page.total;
134	    existing.push(...page.items);
135	    skip += page.items.length;
136	    if (page.items.length === 0) break; // guard against a zero-item page to prevent infinite loop
137	  }
138	
139	  // Map from uiCopy key → full entry object so we can inspect sys.publishedVersion below.
140	  const existingEntryMap = new Map(
141	    existing.map((e) => [e.fields?.key?.['en'], e]).filter(([key]) => Boolean(key)),
142	  );
143	
144	  let created = 0;
145	  let skipped = 0;
146	  let published = 0;
147	
148	  for (const entry of entries) {
149	    const existingEntry = existingEntryMap.get(entry.key);
150	    if (existingEntry) {
151	      if (existingEntry.sys.publishedVersion == null) {
152	        // Entry exists as a draft — publish it now so it is available to the app.
153	        await client.entry.publish(
154	          { environmentId: target, entryId: existingEntry.sys.id },
155	          { sys: existingEntry.sys },
156	        );
157	        log.success(`${entry.key} — draft published`);
158	        published++;
159	      } else {
160	        log.skip(`${entry.key} — already published, skipping`);
161	        skipped++;
162	      }
163	      continue;
164	    }
165	
166	    const created_entry = await client.entry.create(
167	      { environmentId: target, contentTypeId: 'uiCopy' },
168	      {
169	        fields: {
170	          title: { 'en': entry.title },
171	          key: { 'en': entry.key },
172	          value: { 'en': entry.value },
173	          description: { 'en': entry.description },
174	        },
175	      },
176	    );
