/**
 * Shared utilities for Contentful setup scripts.
 * Provides client factory, env validation, and environment polling.
 */

import { createClient as createCMAClient } from 'contentful-management';

export const log = {
  info: (msg) => console.log(`  ℹ️  ${msg}`),
  success: (msg) => console.log(`  ✅  ${msg}`),
  skip: (msg) => console.log(`  ⏭️   ${msg}`),
  warn: (msg) => console.warn(`  ⚠️  ${msg}`),
  error: (msg) => console.error(`  ❌  ${msg}`),
  section: (msg) => console.log(`\n── ${msg} ──`),
};

/**
 * Validates that the required environment variables are set and non-empty.
 * Exits the process with a descriptive message if any are missing.
 * @param {string[]} required
 */
export function checkEnv(required) {
  const missing = required.filter((k) => !process.env[k]);
  if (missing.length) {
    log.error(`Missing env vars: ${missing.join(', ')}`);
    console.error('   Add them to .env (at repo root) and re-run.\n');
    process.exit(1);
  }
}

/**
 * Creates a contentful-management plain client scoped to the project space.
 * @returns {import('contentful-management').PlainClientAPI}
 */
export function createClient() {
  return createCMAClient(
    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
    {
      type: 'plain',
      defaults: { spaceId: process.env.CONTENTFUL_SPACE_ID },
    },
  );
}

/**
 * Polls an environment until its status is 'ready', then returns it.
 * Contentful creates environments asynchronously — this is required after create().
 * @param {import('contentful-management').PlainClientAPI} client
 * @param {string} environmentId
 * @param {number} [timeoutMs=120_000]
 * @returns {Promise<object>}
 */
export async function pollForReady(client, environmentId, timeoutMs = 120_000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const env = await client.environment.get({ environmentId });
      if (env.sys.status?.sys?.id === 'ready') return env;
    } catch (err) {
      // 404 immediately after create() is expected — environment is still being provisioned
      if (err.status !== 404) throw err;
    }
    await new Promise((r) => setTimeout(r, 3_000));
    process.stdout.write('.');
  }
  throw new Error(`Environment '${environmentId}' did not become ready within ${timeoutMs / 1000}s`);
}

/**
 * Returns a sorted list of existing environment IDs in the space.
 * @param {import('contentful-management').PlainClientAPI} client
 * @returns {Promise<string[]>}
 */
export async function getExistingEnvironmentIds(client) {
  const { items } = await client.environment.getMany({ query: { limit: 100 } });
  return items.map((e) => e.sys.id);
}

/**
 * Returns existing locale codes in a given environment.
 * @param {import('contentful-management').PlainClientAPI} client
 * @param {string} environmentId
 * @returns {Promise<string[]>}
 */
export async function getExistingLocaleCodes(client, environmentId) {
  const { items } = await client.locale.getMany({ environmentId, query: { limit: 100 } });
  return items.map((l) => l.code);
}

/**
 * Parses a `--target <env>` flag from argv, defaulting to 'dev'. Exits the process with a
 * descriptive message if the flag is present but has no value following it — extracted verbatim
 * from the three seedXUiCopy.mjs scripts (SFCC-742's seedLoginDrawerUiCopy.mjs first, then
 * SFCC-831/689's seedRegionalPromptUiCopy.mjs and seedDrawerCloseUiCopy.mjs copied it), which had
 * each independently reimplemented this exact logic.
 * @param {string[]} [args]
 * @returns {string}
 */
export function resolveTarget(args = process.argv.slice(2)) {
  const i = args.indexOf('--target');
  const rawTarget = i !== -1 ? args[i + 1] : null;
  if (rawTarget === undefined) {
    // --target flag was present but no value followed it
    console.error('Error: --target requires a value, e.g. --target dev');
    process.exit(1);
  }
  return rawTarget ?? 'dev';
}

/**
 * Seeds a list of `uiCopy` entries into a target Contentful environment: creates and publishes
 * any that don't yet exist, publishes any that exist only as an unpublished draft, and skips any
 * that are already published. Safe to re-run. Extracted verbatim from the same three scripts
 * {@link resolveTarget} was — see that function's own doc comment.
 * @param {import('contentful-management').PlainClientAPI} client
 * @param {string} target
 * @param {{ key: string; title: string; value: string; description: string }[]} entries
 * @returns {Promise<void>}
 */
export async function seedUiCopyEntries(client, target, entries) {
  log.section(`Seeding ${entries.length} uiCopy entries → environment: ${target}`);

  // Fetch all existing uiCopy entries across pages before duplicate checks.
  // contentful-management paginates at 1,000 — a single request may miss entries.
  const existing = [];
  let skip = 0;
  let total = Infinity;
  while (existing.length < total) {
    const page = await client.entry.getMany({
      environmentId: target,
      query: { content_type: 'uiCopy', limit: 1000, skip },
    });
    total = page.total;
    existing.push(...page.items);
    skip += page.items.length;
    if (page.items.length === 0) break; // guard against a zero-item page to prevent infinite loop
  }

  // Map from uiCopy key → full entry object so we can inspect sys.publishedVersion below.
  const existingEntryMap = new Map(
    existing.map((e) => [e.fields?.key?.['en'], e]).filter(([key]) => Boolean(key)),
  );

  let created = 0;
  let skipped = 0;
  let published = 0;

  for (const entry of entries) {
    const existingEntry = existingEntryMap.get(entry.key);
    if (existingEntry) {
      if (existingEntry.sys.publishedVersion == null) {
        // Entry exists as a draft — publish it now so it is available to the app.
        await client.entry.publish(
          { environmentId: target, entryId: existingEntry.sys.id },
          { sys: existingEntry.sys },
        );
        log.success(`${entry.key} — draft published`);
        published++;
      } else {
        log.skip(`${entry.key} — already published, skipping`);
        skipped++;
      }
      continue;
    }

    const created_entry = await client.entry.create(
      { environmentId: target, contentTypeId: 'uiCopy' },
      {
        fields: {
          title: { 'en': entry.title },
          key: { 'en': entry.key },
          value: { 'en': entry.value },
          description: { 'en': entry.description },
        },
      },
    );

    await client.entry.publish(
      { environmentId: target, entryId: created_entry.sys.id },
      { sys: created_entry.sys },
    );

    log.success(`${entry.key}`);
    created++;
  }

  log.section('Done');
  log.info(`Created and published: ${created}`);
  if (published) log.info(`Draft entries published: ${published}`);
  if (skipped) log.info(`Skipped (already published): ${skipped}`);
}

#!/usr/bin/env node
/**
 * One-off seed script — creates the 1 uiCopy entry for ZimmDrawer's close button label
 * (SFCC-831, discovered as a gap while seeding the regional prompt keys — see
 * ~/Dev/zimmerMANN-skills/.runs/SFCC-831/decisions.md for the full history).
 *
 * Usage:
 *   node scripts/contentful/seedDrawerCloseUiCopy.mjs --target dev
 *
 * Targets a single Contentful environment. Defaults to 'dev' if --target is omitted.
 * Skips the entry if its key already exists in the target environment (safe to re-run).
 * The entry is created AND published in one pass.
 *
 * Required env vars (from .env via `npm run env -- init`):
 *   CONTENTFUL_MANAGEMENT_TOKEN
 *   CONTENTFUL_SPACE_ID
 *
 * The value below must match zimmDrawer/index.tsx's `t('drawer.close', 'Close')` call
 * exactly — that component's own inline fallback is the source of truth this script mirrors,
 * not the other way round. This one key is shared by all four ZimmDrawer consumers (the PDP
 * tab drawer, the Wishlist/Login drawer, Find in Boutique, and the regional country/language
 * mismatch prompt) — until this entry is seeded, every one of them renders the English
 * "Close" fallback on every locale, including the EU-domestic sites this build's own feature
 * is meant to speak the right language on.
 */

import { checkEnv, createClient, log, resolveTarget, seedUiCopyEntries } from './setup/_shared.mjs';

/** @type {{ key: string; title: string; value: string; description: string }[]} */
export const ENTRIES = [
  {
    key: 'drawer.close',
    title: 'Drawer — Close Button Label',
    value: 'Close',
    description:
      "Accessible label (aria-label) for the close (X) button on every ZimmDrawer instance " +
      "site-wide — the PDP tab drawer, the Wishlist/Login drawer, Find in Boutique, and the " +
      "regional country/language mismatch prompt all share this one key. Read aloud by screen " +
      "readers; not visible text in the UI. No tokens.",
  },
];

if (import.meta.url === `file://${process.argv[1]}`) {
  const TARGET = resolveTarget();
  checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
  seedUiCopyEntries(createClient(), TARGET, ENTRIES).catch((err) => {
    log.error(err.message ?? String(err));
    process.exit(1);
  });
}

